    /// Decode a v2 document (slots composed as the harness does) → the FLEX root.
    static func flexRoot(_ json: String) throws -> IRComponent {
        let doc = try JSONDecoder().decode(IRDocument.self, from: Data(json.utf8))
        // The container is the root that declares Display FLEX.
        return try XCTUnwrap(doc.components.first { c in
            c.properties.contains { $0.type == "Display" && ValueExtractors.extractKeyword($0.data) == "FLEX" }
        }, "no flex root")
    }
